/**
 * Pchat — help page renderer
 * =====================================================================
 * Renders the Help page from `window.HelpData`, which is generated by
 * `tools/generate-help.js` straight from the project source.
 *
 * Nothing here is hard-coded: if a feature is added to the app the
 * generator picks it up, and if a feature is removed the help page loses
 * it. That is the whole point — the help page cannot drift away from the
 * app.
 */

(function () {
  'use strict';

  const D = window.HelpData || {};
  const $ = (sel, root) => (root || document).querySelector(sel);
  const $$ = (sel, root) => Array.from((root || document).querySelectorAll(sel));

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, (m) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    }[m]));
  }

  function el(html) {
    const t = document.createElement('template');
    t.innerHTML = html.trim();
    return t.content.firstElementChild;
  }

  /* ── Section builders ─────────────────────────────────────────── */

  function buildGettingStarted() {
    const wrap = el('<div></div>');
    const steps = [
      ['Open the app and sign in', 'Use a Google account for a saved room, or skip it — quick rooms need no account at all.'],
      ['Create a room', 'Give it a name, pick a wallpaper, and you get a link and a QR code.'],
      ['Share the link', 'Anyone who opens it picks a name and is in. That is the whole setup.'],
      ['Make it secret (optional)', 'Set a room passphrase before you share. The link then carries no key material at all.'],
    ];
    steps.forEach(([title, body], i) => {
      wrap.appendChild(el(
        '<div class="doc-group">' +
        '<h3><span class="badge badge-accent">' + (i + 1) + '</span> ' + esc(title) + '</h3>' +
        '<p>' + esc(body) + '</p></div>'
      ));
    });
    return wrap;
  }

  function buildScreens() {
    const wrap = el('<div></div>');
    (D.pages || []).forEach((p) => {
      const g = el(
        '<div class="doc-group">' +
        '<h3>' + esc(p.title) + ' <code style="font-size:.7rem;color:var(--muted)">' + esc(p.file) + '</code></h3>' +
        '<p>' + esc(p.blurb) + '</p>' +
        '</div>'
      );
      const inv = (D.controls || {})[p.file] || [];
      if (inv.length) {
        const box = el('<div class="doc-inventory" style="margin-top:.7rem"></div>');
        inv.forEach((c) => {
          box.appendChild(el(
            '<div class="doc-inv-item"><span class="doc-inv-label">' + esc(c.label) +
            '</span><code>' + esc(c.id) + '</code></div>'
          ));
        });
        g.appendChild(box);
      }
      wrap.appendChild(g);
    });
    return wrap;
  }

  function buildGroupList(key) {
    const wrap = el('<div></div>');
    ((D.groups || {})[key] || []).forEach((g) => {
      wrap.appendChild(el(
        '<div class="doc-group"><h3>' + esc(g.title) + '</h3><p>' + esc(g.blurb) + '</p></div>'
      ));
    });
    return wrap;
  }

  function buildInventory(file) {
    const inv = (D.controls || {})[file] || [];
    const box = el('<div class="doc-inventory"></div>');
    if (!inv.length) {
      box.appendChild(el('<p style="color:var(--muted);font-size:.85rem">No buttons on this screen.</p>'));
      return box;
    }
    inv.forEach((c) => {
      box.appendChild(el(
        '<div class="doc-inv-item"><span class="doc-inv-label">' + esc(c.label) +
        '</span><code>' + esc(c.id) + '</code></div>'
      ));
    });
    return box;
  }

  function buildBot() {
    const wrap = el('<div></div>');
    const bot = D.bot || {};
    const intro = el(
      '<div class="doc-group"><h3>How to use it</h3>' +
      '<p>Type <code>' + esc(bot.mention || '@shepu-ai') + '</code> in the message box, then your request. ' +
      'Room commands are understood <strong>on your device</strong> — they never reach the AI provider. ' +
      'Anything that is not a command is answered as a normal question.</p></div>'
    );
    wrap.appendChild(intro);

    (bot.actions || []).forEach((a) => {
      const g = el('<div class="doc-group"><h3>' + esc(a.title) + '</h3><p>' + esc(a.blurb) + '</p></div>');
      const chips = el('<div class="doc-chips"></div>');
      (a.say || []).forEach((s) => {
        const chip = el('<button type="button" class="doc-chip" title="Click to copy">' + esc(s) + '</button>');
        chip.addEventListener('click', () => {
          const done = () => {
            chip.classList.add('copied');
            chip.textContent = 'copied ✓';
            setTimeout(() => { chip.classList.remove('copied'); chip.textContent = s; }, 1400);
          };
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(s).then(done).catch(done);
          } else { done(); }
        });
        chips.appendChild(chip);
      });
      g.appendChild(chips);
      wrap.appendChild(g);
    });

    if ((bot.musicCommands || []).length) {
      const g = el(
        '<div class="doc-group"><h3>Room radio</h3>' +
        '<p>The assistant also controls the room music player.</p></div>'
      );
      const chips = el('<div class="doc-chips"></div>');
      const say = { play: 'gan chalu', stop: 'gan bondho', next: 'gan chenge' };
      bot.musicCommands.forEach((c) => {
        const s = say[c] || c;
        const chip = el('<button type="button" class="doc-chip" title="Click to copy">' + esc(s) + '</button>');
        chip.addEventListener('click', () => {
          const done = () => {
            chip.classList.add('copied'); chip.textContent = 'copied ✓';
            setTimeout(() => { chip.classList.remove('copied'); chip.textContent = s; }, 1400);
          };
          if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(s).then(done).catch(done);
          else done();
        });
        chips.appendChild(chip);
      });
      g.appendChild(chips);
      wrap.appendChild(g);
    }
    return wrap;
  }

  function buildShortcuts() {
    const wrap = el('<div></div>');
    const t = el('<table class="doc-table"><thead><tr><th>Keys</th><th>Where</th><th>What it does</th></tr></thead><tbody></tbody></table>');
    const tb = $('tbody', t);
    (D.shortcuts || []).forEach((s) => {
      tb.appendChild(el('<tr><td><code>' + esc(s.keys) + '</code></td><td>' + esc(s.where) + '</td><td>' + esc(s.blurb) + '</td></tr>'));
    });
    wrap.appendChild(t);
    return wrap;
  }

  function buildData() {
    const wrap = el('<div></div>');
    const st = D.storage || {};

    const lsRows = (st.localStorage || []).map((k) => '<tr><td><code>' + esc(k) + '</code></td><td>browser storage</td></tr>').join('');
    const pat = st.localStoragePatterns || {};
    const patRows = []
      .concat((pat.rooms || []).map((k) => [k, 'one saved quick room per room id']))
      .concat((pat.bot || []).map((k) => [k, "the assistant's own backend identity"]))
      .concat((pat.roomPassword || []).map((k) => [k, 'the exported room key (this tab only)']))
      .concat((pat.relay || []).map((k) => [k, 'your relay server list']))
      .map(([k, d]) => '<tr><td><code>' + esc(k) + '</code></td><td>' + esc(d) + '</td></tr>').join('');

    wrap.appendChild(el(
      '<div class="doc-group"><h3>Where a saved room keeps its messages</h3>' +
      '<p>Each room is a Google Sheet with ' + (D.sheets || []).length + ' tabs. ' +
      'The <code>messages</code> tab holds the conversation, <code>members</code> holds who is in the room, ' +
      'and <code>room_config</code> holds the name, the status and the password verifier.</p></div>'
    ));

    const t = el('<table class="doc-table"><thead><tr><th>Tab</th><th>Columns</th></tr></thead><tbody></tbody></table>');
    const tb = $('tbody', t);
    (D.sheets || []).forEach((s) => {
      tb.appendChild(el('<tr><td><code>' + esc(s.name) + '</code></td><td><code style="font-size:.75rem">' + esc(s.columns.join(', ')) + '</code></td></tr>'));
    });
    wrap.appendChild(t);

    wrap.appendChild(el(
      '<div class="doc-group" style="margin-top:1rem"><h3>What stays on your device</h3>' +
      '<p>Nothing you type leaves your device except the messages themselves. These are the local keys the app keeps — ' +
      'clearing them from Settings → Privacy removes every trace of this room from the browser.</p></div>'
    ));

    const t2 = el('<table class="doc-table"><thead><tr><th>Key</th><th>What it holds</th></tr></thead><tbody></tbody></table>');
    const tb2 = $('tbody', t2);
    const row = (k, d) => tb2.appendChild(el('<tr><td><code>' + esc(k) + '</code></td><td>' + esc(d) + '</td></tr>'));
    (st.localStorage || []).forEach((k) => row(k, 'app setting'));
    if (patRows) { /* pattern rows are described in their own group below */ }
    const patTable = el('<table class="doc-table"><thead><tr><th>Key pattern</th><th>What it holds</th></tr></thead><tbody>' + patRows + '</tbody></table>');
    wrap.appendChild(patTable);
    (st.sessionStorage || []).forEach((k) => row(k, 'the exported room key (this tab only)'));
    wrap.appendChild(t2);

    wrap.appendChild(el(
      '<div class="doc-group" style="margin-top:1rem"><h3>Offline cache</h3>' +
      '<p>Messages and members are cached in IndexedDB (' + esc((st.indexeddb || {}).name || 'SHEPURooms') +
      ', version ' + esc((st.indexeddb || {}).version || 1) + ') so a room opens instantly and keeps working offline. ' +
      'The cache is a cache — a failed write never stops a message from being delivered.</p></div>'
    ));
    return wrap;
  }

  function buildHowItWorks() {
    const wrap = el('<div></div>');
    const rel = D.relay || {};
    const enc = D.encryption || {};

    wrap.appendChild(el(
      '<div class="doc-group"><h3>Two ways a message travels</h3>' +
      '<p>Messages are sent over <strong>two independent transports</strong> at once — a direct peer-to-peer ' +
      'connection and a cloud relay. If one is blocked, the other still delivers. Nothing is lost because a ' +
      'network refused it.</p></div>'
    ));

    const t = el('<table class="doc-table"><thead><tr><th>Relay server</th><th>Status</th></tr></thead><tbody></tbody></table>');
    const tb = $('tbody', t);
    (rel.servers || []).forEach((s) => {
      tb.appendChild(el('<tr><td><code>' + esc(s) + '</code></td><td>in use — all of them are used at once, so one being down does not matter</td></tr>'));
    });
    wrap.appendChild(t);

    wrap.appendChild(el(
      '<div class="doc-group" style="margin-top:1rem"><h3>Relay payloads</h3>' +
      '<p>These are the kinds of thing that travel over the relay: ' +
      esc((rel.payloadTypes || []).join(', ')) + '. ' +
      'The channel name is derived from the room secret, so it cannot be guessed without the link. ' +
      'A message longer than ' + esc(rel.maxBytes || 4096) + ' bytes is split into parts and stitched back together on the other side, ' +
      'so a long message still arrives as one bubble.</p></div>'
    ));

    wrap.appendChild(el(
      '<div class="doc-group" style="margin-top:1rem"><h3>Encryption</h3>' +
      '<p>When a room passphrase is set, every new message is encrypted on the sending device before it goes anywhere, ' +
      'using ' + esc(enc.cipher || 'AES-GCM') + ' with a key derived by ' + esc(enc.kdf || 'PBKDF2') + ' ' +
      esc(enc.iterations || 0) + ' rounds. The key never leaves the device and the relay only ever sees ciphertext. ' +
      'Without a passphrase a room is not encrypted — it is private, not secret.</p></div>'
    ));

    const cfgRows = (D.config || [])
      .filter((c) => /SYNC|PRESENCE|MAX_MESSAGE|RETRY|BACKOFF|ROOM_ID|TOKEN|IDB/.test(c.key))
      .map((c) => '<tr><td><code>' + esc(c.key) + '</code></td><td><code>' + esc(c.value) + '</code></td></tr>')
      .join('');
    if (cfgRows) {
      wrap.appendChild(el(
        '<div class="doc-group" style="margin-top:1rem"><h3>Timing and limits</h3>' +
        '<p>These are the numbers the app actually runs on.</p></div>'
      ));
      wrap.appendChild(el('<table class="doc-table"><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody>' + cfgRows + '</tbody></table>'));
    }
    return wrap;
  }

  function buildTroubleshooting() {
    const wrap = el('<div></div>');
    const items = (D.troubleshooting || []);
    items.forEach((it) => {
      wrap.appendChild(el(
        '<div class="doc-group"><h3>' + esc(it.q) + '</h3><p>' + esc(it.a) + '</p></div>'
      ));
    });
    return wrap;
  }

  /* ── Mount ────────────────────────────────────────────────────── */

  const BUILDERS = {
    'getting-started': buildGettingStarted,
    'screens': buildScreens,
    'room': buildGroupList.bind(null, 'room'),
    'room-controls': (r) => buildInventory('room.html'),
    'dashboard': buildGroupList.bind(null, 'dashboard'),
    'friends': buildGroupList.bind(null, 'friends'),
    'owner': buildGroupList.bind(null, 'owner'),
    'owner-controls': (r) => buildInventory('owner.html'),
    'settings': buildGroupList.bind(null, 'settings'),
    'settings-controls': (r) => buildInventory('settings.html'),
    'assistant': buildBot,
    'shortcuts': buildShortcuts,
    'data': buildData,
    'how-it-works': buildHowItWorks,
    'troubleshooting': buildTroubleshooting,
  };

  function mount() {
    const data = window.HelpData;
    const navEl = $('#doc-nav');
    const mainEl = $('#doc-main');
    if (!navEl || !mainEl) return;
    if (!data) {
      mainEl.appendChild(el(
        '<div class="doc-empty visible"><h3>Help content was not generated</h3>' +
        '<p>Run <code>node tools/generate-help.js</code> to build <code>js/help-data.js</code> from the project source.</p></div>'
      ));
      return;
    }

    // Navigation + sections come from the HTML, so the page structure is
    // visible in the markup and the content is injected from the data.
    $$('.doc-section').forEach((sec) => {
      const key = sec.dataset.doc;
      const build = BUILDERS[key];
      const body = sec.querySelector('.doc-body');
      if (build && body) {
        try {
          body.appendChild(build());
        } catch (e) {
          console.warn('[Help] could not build section "' + key + '":', e);
        }
      }
      if (!navEl) return;
      const title = sec.dataset.title || key;
      const btn = el(
        '<button type="button" class="sidebar-item" data-target="' + key + '">' +
        '<span class="item-label">' + esc(title) + '</span></button>'
      );
      btn.addEventListener('click', () => {
        $$('.doc-section').forEach((s) => s.hidden = s !== sec);
        $$('#doc-nav .sidebar-item').forEach((b) => b.classList.remove('active'));
        btn.classList.add('active');
        sec.scrollIntoView({ behavior: 'smooth', block: 'start' });
        try { history.replaceState(null, '', '#' + key); } catch (e) { /* ignore */ }
      });
      navEl.appendChild(btn);
    });

    // Show the section the visitor linked to, or the first one.
    const wanted = (location.hash || '').replace('#', '');
    const target = $$('.doc-section').find((s) => s.dataset.doc === wanted) || $$('.doc-section')[0];
    $$('.doc-section').forEach((s) => { s.hidden = s !== target; });
    const active = $('#doc-nav .sidebar-item[data-target="' + target.dataset.doc + '"]');
    if (active) active.classList.add('active');

    // Live search across every section.
    const input = $('#doc-search');
    const empty = $('#doc-empty');
    if (input) {
      const run = () => {
        const q = input.value.trim().toLowerCase();
        input.parentElement.classList.toggle('has-value', !!q);
        let hits = 0;
        $$('.doc-section').forEach((sec) => {
          if (!q) { sec.hidden = sec !== target; return; }
          const match = sec.textContent.toLowerCase().includes(q);
          sec.hidden = !match;
          if (match) hits++;
        });
        if (empty) empty.classList.toggle('visible', q && hits === 0);
        if (q && hits) {
          const first = $$('.doc-section').find((s) => !s.hidden);
          if (first) first.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      };
      input.addEventListener('input', run);
      const clear = $('#doc-search-clear');
      if (clear) clear.addEventListener('click', () => { input.value = ''; run(); input.focus(); });
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mount);
  else mount();
})();
